using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net.Http;
using System.Reflection;
using System.Security.Cryptography;
using System.Threading.Tasks;
internal static class CompanionUpdateDownload {
 internal static readonly string[] Required={"CompagnonDofus.exe","SkiaSharp.dll","libSkiaSharp.dll","System.Memory.dll","System.Buffers.dll","System.Runtime.CompilerServices.Unsafe.dll","System.Numerics.Vectors.dll","THIRD_PARTY_NOTICES.txt"};
 internal static string Stage(string archive,string folder,Version version){Directory.CreateDirectory(folder);using(var zip=ZipFile.OpenRead(archive)){foreach(string name in Required){var entries=zip.Entries.Where(x=>x.FullName==name).ToArray();if(entries.Length!=1||entries[0].Length<1||entries[0].Length>150L*1024*1024)throw new InvalidDataException("Archive incomplète : "+name);entries[0].ExtractToFile(Path.Combine(folder,name));}}string exe=Path.Combine(folder,Required[0]);var assembly=AssemblyName.GetAssemblyName(exe);if(assembly.Name!="CompagnonDofus"||assembly.Version!=version)throw new InvalidDataException("Version téléchargée incorrecte.");return exe;}
 internal static async Task<string> Fetch(string url,Version version,Action<int> progress){string expected="https://github.com/Chaavesss/Mon-Espace/releases/download/compagnon-dofus-v"+version.ToString(3)+"/CompagnonDofus.zip";if(url!=expected)throw new InvalidDataException("Le ZIP de cette version n’est pas encore disponible.");string folder=Path.Combine(CompanionProgram.Root,"Updates",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string zip=Path.Combine(folder,"package.zip");using(var http=new HttpClient{Timeout=TimeSpan.FromMinutes(5)}){http.DefaultRequestHeaders.UserAgent.ParseAdd("CompagnonDofus/"+CompanionUpdates.Current);string hashText=await http.GetStringAsync(url.Replace("CompagnonDofus.zip","SHA256.txt"));string expectedHash=hashText.Trim().Split(new[]{' ','\t','\r','\n'},StringSplitOptions.RemoveEmptyEntries)[0];if(!System.Text.RegularExpressions.Regex.IsMatch(expectedHash,"^[a-fA-F0-9]{64}$"))throw new InvalidDataException("Empreinte de téléchargement invalide.");using(var response=await http.GetAsync(url,HttpCompletionOption.ResponseHeadersRead)){response.EnsureSuccessStatusCode();long size=response.Content.Headers.ContentLength??0;if(size>250L*1024*1024)throw new InvalidDataException("Archive trop volumineuse.");using(var input=await response.Content.ReadAsStreamAsync())using(var output=File.Create(zip)){byte[] buffer=new byte[81920];int count;long total=0;while((count=await input.ReadAsync(buffer,0,buffer.Length))>0){total+=count;if(total>250L*1024*1024)throw new InvalidDataException("Archive trop volumineuse.");await output.WriteAsync(buffer,0,count);progress(size>0?(int)(100*total/size):0);}}}using(var sha=SHA256.Create())using(var file=File.OpenRead(zip)){string actual=BitConverter.ToString(sha.ComputeHash(file)).Replace("-","");if(!actual.Equals(expectedHash,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Le téléchargement est endommagé. Réessayez.");}}return Stage(zip,Path.Combine(folder,"ready"),version);}
}
internal sealed partial class CompanionWindow {
 bool downloadingUpdate;
 async void DownloadUpdate(){if(testing||downloadingUpdate||String.IsNullOrEmpty(updateUrl))return;downloadingUpdate=true;UpdateNotice();try{updateMessage="Téléchargement de la mise à jour…";UpdateNotice();string target=await CompanionUpdateDownload.Fetch(updateUrl,new Version(updateVersion+".0"),percent=>{updateMessage="Téléchargement de la mise à jour · "+percent+" %";UpdateNotice();});if(closing)return;updateMessage="Mise à jour téléchargée · prête à installer";UpdateNotice();if(System.Windows.MessageBox.Show("La mise à jour est prête. Fermer le compagnon pour l’installer et le relancer ? Votre progression est conservée.","Mise à jour du compagnon",System.Windows.MessageBoxButton.YesNo)!=System.Windows.MessageBoxResult.Yes)return;if(busy)throw new IOException("Attendez la fin du chargement du guide, puis réessayez.");store.Save();System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(target,"--finish-update "+System.Diagnostics.Process.GetCurrentProcess().Id){UseShellExecute=true});Close();}catch(Exception ex){updateMessage="Mise à jour non installée : "+ex.Message;}finally{downloadingUpdate=false;UpdateNotice();}}
}
